#!/usr/bin/env python3
"""news-image-20261119 entry: the world news of 19 November 2026 in one image.

A dark "night desk" magazine cover: masthead, one hero story (Trump, Xi
and Putin meeting in Shenzhen) and five more stories in a 2x3 grid --
the Kerch Bridge hit again, a tanker struck in the Gulf, Israel's push
into Gaza, Anthropic's record IPO, GTA VI's global rollout, and the EU's
Ukraine loan. Every illustration is original flat art drawn with PIL;
all on-image text is rendered with PIL, so every word is spelled
correctly. The image is embedded below (zlib-compressed, base64), so
this program needs nothing but the Python standard library, no network
and no files beside itself. Decoding fixed bytes is fully deterministic:
every run writes byte-identical output.
"""

import base64
import os
import zlib

_IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = zlib.decompress(base64.b64decode(_IMAGE_B64))
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
